        // send gate asks (gate.ts:92-103). exists(revoked) is a different
        // question, and it is the wrong one for a contact who revoked once and
        // has since re-consented.
        const [latest] = await tx
          .select({ status: consents.status, occurredAt: consents.occurredAt })
          .from(consents)
          .where(and(eq(consents.contactId, item.contactId), eq(consents.channel, "sms")))
          .orderBy(desc(consents.occurredAt))
